INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Morro Dois Irmãos', 'Vidigal', NULL, 'SUL', -22.9886, -43.2358, 20, NULL, NULL, 'Acesso 24 horas.', 'FACIL', 3, 90, 533, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Vista icônica de Ipanema, Leblon, Lagoa e Cristo a partir do Vidigal.', 'A trilha começa no alto da comunidade do Vidigal e sobe por mata até o mirante do Dois Irmãos. É curta, mas tem trechos íngremes. O pôr do sol visto dali é um dos mais disputados da cidade.', 'Vá até a Av. Niemeyer, no Vidigal, e suba de mototáxi ou van até a Vila Olímpica, onde a trilha começa.', TRUE);
