INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Morro da Babilônia', 'Leme', NULL, 'SUL', -22.9573942, -43.1698023, 0, NULL, NULL, 'Acesso 24 horas.', 'FACIL', 4, 60, 235, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Mirante com vista de Copacabana, guiado por moradores da comunidade.', 'Trilha curta em área reflorestada pelos próprios moradores. Oferece uma das melhores vistas da orla de Copacabana e do Pão de Açúcar.', 'Entrada da trilha na Ladeira Ary Barroso, no Leme.', FALSE);
