INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Morro da Urca', 'Urca', NULL, 'SUL', -22.9508198, -43.1639861, 0, '08:00', '17:00', 'Das 8h às 17h.', 'FACIL', 4.5, 60, 220, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Pela Pista Cláudio Coutinho até a vista do Pão de Açúcar e de Botafogo.', 'A trilha parte da Pista Cláudio Coutinho, na Praia Vermelha, e sobe em mata até o alto do Morro da Urca, onde fica a estação intermediária do bondinho. É comum ver micos e saguis no caminho.', 'Praça General Tibúrcio, Praia Vermelha. Ônibus, ou metrô até Botafogo e depois ônibus.', TRUE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Morro_da_Urca%2C_Rio_de_Janeiro%2C_RJ.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Morro_da_Urca%2C_Rio_de_Janeiro%2C_RJ.jpg' FROM TRILHA WHERE nome = 'Morro da Urca';
