INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Morro do Leme', 'Leme', NULL, 'SUL', -22.9633201, -43.1610497, 10, '09:00', NULL, 'Abre às 9h.', 'FACIL', 2.2, 45, 124, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Caminho calçado dentro do Forte Duque de Caxias até o alto do morro, com vista de Copacabana e da Baía de Guanabara.', 'A subida começa na entrada do Forte Duque de Caxias, no fim da praia do Leme, e segue por um caminho calçado à sombra da mata até o topo. De lá se veem a orla de Copacabana, o Pão de Açúcar e a entrada da Baía de Guanabara.', 'Entrada do Forte Duque de Caxias, no fim da praia do Leme.', FALSE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Morro_do_Leme_5.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Morro_do_Leme_5.jpg' FROM TRILHA WHERE nome = 'Morro do Leme';
