INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Mirante do Sacopã', 'Lagoa', NULL, 'SUL', -22.9716958, -43.2056508, 0, '08:00', '17:00', 'Das 8h às 17h.', 'FACIL', 0.6, 50, NULL, 'CIRCUITO', 'CAMINHADA', 'ABERTA', 'Circuito curto até um mirante sobre a Lagoa Rodrigo de Freitas, com o Cristo e o Dois Irmãos ao fundo.', 'Trilha em circuito, curta e sombreada, que chega a um mirante sobre a Lagoa Rodrigo de Freitas. Boa opção para quem quer uma vista ampla sem encarar uma subida longa.', 'Portaria do parque, na Lagoa.', FALSE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vista_do_Mirante_do_Sacop%C3%A3_3.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Vista_do_Mirante_do_Sacop%C3%A3_3.jpg' FROM TRILHA WHERE nome = 'Mirante do Sacopã';
