INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Morro dos Cabritos', 'Lagoa / Copacabana', NULL, 'SUL', -22.9689314, -43.1973691, 0, NULL, NULL, 'Acesso 24 horas.', 'FACIL', 0, NULL, 378, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Morro entre Copacabana e a Lagoa, com vista para os dois lados a partir do cume, a 378 m.', 'Subida pela mata no maciço que separa Copacabana da Lagoa Rodrigo de Freitas. Distância e duração ainda não foram levantadas: informe-se com guias locais antes de ir.', 'Acesso pela Lagoa ou por Copacabana; o ponto de partida depende do caminho escolhido.', FALSE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Morro_dos_Cabritos_-_panoramio.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Morro_dos_Cabritos_-_panoramio.jpg' FROM TRILHA WHERE nome = 'Morro dos Cabritos';
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 1, 'https://commons.wikimedia.org/wiki/Special:FilePath/Morro_dos_Cabritos_-_panoramio_%2827%29.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Morro_dos_Cabritos_-_panoramio_%2827%29.jpg' FROM TRILHA WHERE nome = 'Morro dos Cabritos';
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Pico da Tijuca e Tijuca Mirim', 'Alto da Boa Vista', 'Parque Nacional da Tijuca · Floresta da Tijuca', 'NORTE', -22.9440031, -43.2867068, 0, '06:00', '18:00', 'Entrada das 6h às 17h; saída até 18h.', 'MEDIO', 4, 120, 1022, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'O ponto mais alto do Parque Nacional da Tijuca, com escadaria esculpida na rocha.', 'Partindo do Bom Retiro, a trilha atravessa a Floresta da Tijuca e termina em uma escadaria de 117 degraus talhados na rocha. Do topo se veem a Zona Norte, a Baía de Guanabara e, em dias limpos, a Serra dos Órgãos. No caminho dá para subir também o Tijuca Mirim, cume vizinho.', 'Entrada do parque pela Praça Afonso Viseu, no Alto da Boa Vista; siga pela estrada interna até o Largo do Bom Retiro, onde a trilha começa.', TRUE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vista_do_Pico_da_Tijuca.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Vista_do_Pico_da_Tijuca.jpg' FROM TRILHA WHERE nome = 'Pico da Tijuca e Tijuca Mirim';
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 1, 'https://commons.wikimedia.org/wiki/Special:FilePath/Escadaria_do_Pico_da_Tijuca.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Escadaria_do_Pico_da_Tijuca.jpg' FROM TRILHA WHERE nome = 'Pico da Tijuca e Tijuca Mirim';
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pico_da_Tijuca_ao_anoitecer.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Pico_da_Tijuca_ao_anoitecer.jpg' FROM TRILHA WHERE nome = 'Pico da Tijuca e Tijuca Mirim';
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Bico do Papagaio', 'Alto da Boa Vista', 'Parque Nacional da Tijuca · Floresta da Tijuca', 'NORTE', -22.9537071, -43.3009272, 0, '06:00', '17:00', 'Entrada das 6h às 17h.', 'MEDIO', 5, 180, 989, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Cume de 989 m no Parque Nacional da Tijuca, com mirante sobre a Barra da Tijuca e Jacarepaguá.', 'Sai do Largo do Bom Retiro e divide parte do caminho com a trilha do Pico da Tijuca. O topo, em forma de bico, tem vista ampla para a Zona Oeste e o litoral.', 'Entrada do parque pela Praça Afonso Viseu, no Alto da Boa Vista; siga pela estrada interna até o Largo do Bom Retiro.', FALSE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vis%C3%A3o_do_alto_do_Bico_do_Papagaio_na_floresta_da_tijuca.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Vis%C3%A3o_do_alto_do_Bico_do_Papagaio_na_floresta_da_tijuca.jpg' FROM TRILHA WHERE nome = 'Bico do Papagaio';
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 1, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pico_do_Papagaio_Floresta_da_Tijuca.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Pico_do_Papagaio_Floresta_da_Tijuca.jpg' FROM TRILHA WHERE nome = 'Bico do Papagaio';
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Morro da Cocanha', 'Alto da Boa Vista', 'Parque Nacional da Tijuca · Floresta da Tijuca', 'NORTE', -22.9587485, -43.3006533, 0, '06:00', '18:00', 'Entrada das 6h às 17h; saída até 18h.', 'MEDIO', 8, 180, 987, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Trilha longa a partir do Bom Retiro até um cume de 987 m com vista da Barra da Tijuca.', 'Uma das caminhadas mais longas do setor Floresta da Tijuca, com cerca de 8 km ida e volta. O esforço é recompensado no alto, com vista da Barra da Tijuca e das lagoas da Zona Oeste.', 'Entrada do parque pela Praça Afonso Viseu, no Alto da Boa Vista; siga pela estrada interna até o Largo do Bom Retiro.', FALSE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vis%C3%A3o_da_Barra_da_Tijuca_no_Morro_da_Cocanha.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Vis%C3%A3o_da_Barra_da_Tijuca_no_Morro_da_Cocanha.jpg' FROM TRILHA WHERE nome = 'Morro da Cocanha';
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 1, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vis%C3%A3o_da_Barra_da_Tijuca_em_Morro_da_Cocanha.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Vis%C3%A3o_da_Barra_da_Tijuca_em_Morro_da_Cocanha.jpg' FROM TRILHA WHERE nome = 'Morro da Cocanha';
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vis%C3%A3o_da_Barra_da_Tijuca_no_Morro_da_Cocanha_2.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Vis%C3%A3o_da_Barra_da_Tijuca_no_Morro_da_Cocanha_2.jpg' FROM TRILHA WHERE nome = 'Morro da Cocanha';
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Morro do Archer', 'Alto da Boa Vista', 'Parque Nacional da Tijuca · Floresta da Tijuca', 'NORTE', -22.9501337, -43.2912978, 0, '06:00', '17:00', 'Entrada das 6h às 17h.', 'FACIL', 0.8, NULL, 813, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Subida curta a partir do Bom Retiro até o morro que homenageia o Major Archer, responsável pelo reflorestamento da Floresta da Tijuca.', 'Desvio de cerca de 400 m a partir do Largo do Bom Retiro, fácil de combinar com outras trilhas do setor. O nome lembra Manuel Gomes Archer, que comandou o replantio da floresta no século XIX.', 'Entrada do parque pela Praça Afonso Viseu, no Alto da Boa Vista; siga pela estrada interna até o Largo do Bom Retiro.', FALSE);
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Morro do Visconde', 'Alto da Boa Vista', 'Parque Nacional da Tijuca · Floresta da Tijuca', 'NORTE', -22.9612, -43.2788, 0, '06:00', '18:00', 'Entrada das 6h às 17h; saída até 18h.', 'FACIL', 1.5, 45, 535, 'IDA_E_VOLTA', 'CAMINHADA', 'MANUTENCAO', 'Trilha curta que parte do estacionamento da Cascatinha Taunay. Em manutenção no momento.', 'Caminhada de cerca de 1,5 km ida e volta pela mata, a partir da área da Cascatinha Taunay. A trilha está em manutenção: confira a situação com o parque antes de ir.', 'Entrada do parque pela Praça Afonso Viseu, no Alto da Boa Vista; siga pela estrada interna até o estacionamento da Cascatinha Taunay.', FALSE);
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Pedra do Conde', 'Alto da Boa Vista', 'Parque Nacional da Tijuca · Floresta da Tijuca', 'NORTE', -22.9488948, -43.2739989, 0, '06:00', '17:00', 'Entrada das 6h às 17h.', 'FACIL', 3.5, 120, 817, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Mirante de 817 m com vista para o Pico da Tijuca e o Sumaré, saindo do estacionamento da Capela Mayrink.', 'Trilha de cerca de 3,5 km ida e volta pela Floresta da Tijuca. Do alto da pedra se veem o Pico da Tijuca, o Tijuca Mirim e o Sumaré.', 'Entrada do parque pela Praça Afonso Viseu, no Alto da Boa Vista; siga pela estrada interna até o estacionamento da Capela Mayrink.', FALSE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pico_da_Tijuca_%5E_Tijuquinha_seen_from_Pedra_do_Conde%5E_-_panoramio.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Pico_da_Tijuca_%5E_Tijuquinha_seen_from_Pedra_do_Conde%5E_-_panoramio.jpg' FROM TRILHA WHERE nome = 'Pedra do Conde';
