INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Morro do Anhanguera', 'Alto da Boa Vista', 'Parque Nacional da Tijuca · Floresta da Tijuca', 'NORTE', -22.9438204, -43.2727406, 0, '06:00', '18:00', 'Entrada das 6h às 17h; saída até 18h.', 'FACIL', 4.5, 120, 693, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Cume de 693 m perto da Capela Mayrink, com vista para a Pedra do Conde.', 'Sai do estacionamento da Capela Mayrink e sobe pela mata em cerca de 2 horas ida e volta. Dá para combinar com a Pedra do Conde, que fica na mesma região.', 'Entrada do parque pela Praça Afonso Viseu, no Alto da Boa Vista; siga pela estrada interna até o estacionamento da Capela Mayrink.', FALSE);
