INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Cachoeira das Almas', 'Alto da Boa Vista', 'Parque Nacional da Tijuca · Floresta da Tijuca', 'NORTE', -22.948637, -43.2868361, 0, '06:00', '17:00', 'Entrada das 6h às 17h.', 'FACIL', 2, 30, NULL, 'CIRCUITO', 'CACHOEIRA', 'ABERTA', 'Circuito curto até uma das cachoeiras mais conhecidas da Floresta da Tijuca.', 'Caminhada leve de cerca de 2 km em circuito, a partir do estacionamento do restaurante, dentro do parque. Boa opção para ir com crianças.', 'Entrada do parque pela Praça Afonso Viseu, no Alto da Boa Vista; siga pela estrada interna até o estacionamento do restaurante.', FALSE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/PNTijuca-CachoeiraAlmas4.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:PNTijuca-CachoeiraAlmas4.jpg' FROM TRILHA WHERE nome = 'Cachoeira das Almas';
