INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Castelos da Taquara', 'Alto da Boa Vista', 'Parque Nacional da Tijuca · Floresta da Tijuca', 'NORTE', -22.942, -43.308, 0, '06:00', '18:00', 'Entrada das 6h às 17h; saída até 18h.', 'DIFICIL', 8, 180, 774, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Formações rochosas no alto da Floresta da Tijuca, com vista para Jacarepaguá.', 'Trilha longa e difícil, com cerca de 8 km ida e volta, que leva a afloramentos de rocha conhecidos como castelos, voltados para a Taquara e a Baixada de Jacarepaguá.', 'Entrada do parque pela Praça Afonso Viseu, no Alto da Boa Vista; siga pela estrada interna até o início da trilha.', FALSE);
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Circuito das Grutas e Cachoeiras', 'Alto da Boa Vista', 'Parque Nacional da Tijuca · Floresta da Tijuca', 'NORTE', -22.953, -43.288, 0, '06:00', '17:00', 'Entrada das 6h às 17h.', 'FACIL', 6, 120, NULL, 'CIRCUITO', 'CACHOEIRA', 'ABERTA', 'Circuito de 6 km por grutas e pequenas quedas d''água da Floresta da Tijuca.', 'Roteiro em circuito que passa por grutas formadas entre blocos de pedra e por cachoeiras no caminho. Leve lanterna para explorar as grutas.', 'Entrada do parque pela Praça Afonso Viseu, no Alto da Boa Vista; siga pela estrada interna até o início da trilha.', FALSE);
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Cascata Gabriela', 'Alto da Boa Vista', 'Parque Nacional da Tijuca · Floresta da Tijuca', 'NORTE', -22.9544793, -43.2891339, 0, '06:00', '18:00', 'Entrada das 6h às 17h; saída até 18h.', 'FACIL', 0.5, 15, NULL, 'IDA_E_VOLTA', 'CACHOEIRA', 'ABERTA', 'Cascata a poucos minutos do estacionamento do restaurante, na Floresta da Tijuca.', 'Caminhada de cerca de 15 minutos ida e volta, ótima para quem está com crianças ou quer só um passeio rápido.', 'Entrada do parque pela Praça Afonso Viseu, no Alto da Boa Vista; siga pela estrada interna até o estacionamento do restaurante.', FALSE);
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Cascata da Baronesa', 'Alto da Boa Vista', 'Parque Nacional da Tijuca · Floresta da Tijuca', 'NORTE', -22.954198, -43.2914948, 0, '06:00', '17:00', 'Entrada das 6h às 17h.', 'FACIL', 0.05, 5, NULL, 'IDA_E_VOLTA', 'CACHOEIRA', 'ABERTA', 'Pequena queda d''água à beira da estrada da Floresta da Tijuca, a poucos passos do carro.', 'Praticamente sem caminhada: são cerca de 50 metros até a cascata. Uma parada rápida para quem percorre o parque de carro ou de bicicleta.', 'Entrada do parque pela Praça Afonso Viseu, no Alto da Boa Vista; siga pela estrada interna até a cascata, que fica junto à estrada.', FALSE);
