INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Cachoeira do Amor', 'Alto da Boa Vista', NULL, 'NORTE', -22.9672069, -43.2799453, 0, NULL, NULL, 'Acesso 24 horas.', 'FACIL', 0, NULL, NULL, 'IDA_E_VOLTA', 'CACHOEIRA', 'ABERTA', 'Cachoeira no Alto da Boa Vista, na região da Floresta da Tijuca.', 'Trilha de acesso no Alto da Boa Vista, aberta 24 horas. Distância e duração ainda não foram levantadas.', 'Trilha de acesso no Alto da Boa Vista.', FALSE);
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Cachoeira dos Primatas', 'Jardim Botânico / Horto', 'Parque Nacional da Tijuca · Serra da Carioca', 'SUL', -22.9583731, -43.2280543, 0, NULL, NULL, 'Acesso 24 horas.', 'FACIL', 1.5, 60, NULL, 'CIRCUITO', 'CACHOEIRA', 'ABERTA', 'Poço de água gelada no meio da mata, ideal para dias quentes.', 'Caminhada tranquila na Serra da Carioca até uma pequena cachoeira com poço. Boa opção para famílias.', 'Início da trilha na Serra da Carioca, acima do Jardim Botânico.', FALSE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cachoeira_-_Floresta_da_Tijuca%2C_Rio_de_Janeiro%2C_Brazil.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Cachoeira_-_Floresta_da_Tijuca%2C_Rio_de_Janeiro%2C_Brazil.jpg' FROM TRILHA WHERE nome = 'Cachoeira dos Primatas';
