INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Cachoeira do Jequitibá', 'Jardim Botânico / Horto', 'Parque Nacional da Tijuca · Serra da Carioca', 'SUL', -22.9628, -43.24, 0, NULL, NULL, 'Acesso 24 horas.', 'FACIL', 0.5, 15, NULL, 'CIRCUITO', 'CACHOEIRA', 'ABERTA', 'Pequena queda d''água no Horto, um pouco acima da Cachoeira do Horto.', 'Circuito de cerca de 500 m pela mata da Serra da Carioca. Dá para emendar com as outras cachoeiras do Horto.', 'Início da trilha no Horto, subindo a Estrada Dona Castorina.', FALSE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cachoeira_no_Horto.JPG?width=1280', 'https://commons.wikimedia.org/wiki/File:Cachoeira_no_Horto.JPG' FROM TRILHA WHERE nome = 'Cachoeira do Jequitibá';
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Cachoeira da Gruta', 'Jardim Botânico / Horto', 'Parque Nacional da Tijuca · Serra da Carioca', 'SUL', -22.9616543, -43.2381087, 0, NULL, NULL, 'Acesso 24 horas.', 'FACIL', 0.5, 15, NULL, 'CIRCUITO', 'CACHOEIRA', 'ABERTA', 'Cachoeira a 15 minutos de caminhada no Horto, na Serra da Carioca.', 'Circuito curto de cerca de 500 m pela mata. Pode ser feito junto com as cachoeiras do Jequitibá e do Horto.', 'Início da trilha no Horto, subindo a Estrada Dona Castorina.', FALSE);
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Cachoeira Imperatriz', 'Jardim Botânico / Horto', 'Parque Nacional da Tijuca · Serra da Carioca', 'SUL', -22.9668, -43.2434, 0, NULL, NULL, 'Acesso 24 horas.', 'FACIL', 0, NULL, NULL, 'CIRCUITO', 'CACHOEIRA', 'ABERTA', 'Cachoeira na região do Solar da Imperatriz, no Horto.', 'Circuito na Serra da Carioca, com acesso aberto 24 horas. Distância e duração ainda não foram levantadas.', 'Região do Solar da Imperatriz, na Estrada Dona Castorina (Horto).', FALSE);
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Cachoeiras do Horto', 'Jardim Botânico / Horto', 'Parque Nacional da Tijuca · Serra da Carioca', 'SUL', -22.9650043, -43.2473251, 0, NULL, NULL, 'Acesso 24 horas.', 'FACIL', 1, 30, NULL, 'CIRCUITO', 'CACHOEIRA', 'ABERTA', 'Circuito de 1 km pelas cachoeiras do Horto, no Jardim Botânico.', 'Caminhada curta e sombreada que passa por pequenas quedas d''água na Serra da Carioca. Uma das cachoeiras mais fáceis de alcançar a partir da Zona Sul.', 'Estrada Dona Castorina, no Horto, perto do ponto final da linha de ônibus 409.', FALSE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Trilha_Cachoeira_do_Horto.JPG?width=1280', 'https://commons.wikimedia.org/wiki/File:Trilha_Cachoeira_do_Horto.JPG' FROM TRILHA WHERE nome = 'Cachoeiras do Horto';
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Morro do Corcovado', 'Jardim Botânico', 'Parque Nacional da Tijuca · Serra da Carioca', 'SUL', -22.9594149, -43.211889, 0, '08:00', NULL, 'Abre às 8h.', 'MEDIO', 2.5, 180, 710, 'IDA_E_VOLTA', 'ESCALAMINHADA', 'ABERTA', 'Subida pela mata do Parque Lage até o Cristo Redentor, com correntes em trechos de rocha.', 'Do Parque Lage, a trilha sobe em ritmo constante pela Mata Atlântica, passa por pequenas quedas d''água e tem trechos com correntes. Termina na base do Cristo; a entrada no monumento é paga à parte.', 'Rua Jardim Botânico, 414 (Parque Lage), onde a trilha começa.', FALSE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Corcovado_emoldurado_no_Parque_Lage.JPG?width=1280', 'https://commons.wikimedia.org/wiki/File:Corcovado_emoldurado_no_Parque_Lage.JPG' FROM TRILHA WHERE nome = 'Morro do Corcovado';
