INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/View_of_Corcovado_from_Sugarloaf_Mountain-Pao_de_Acucar_at_Sunset_-_Rio_de_Janeiro_-_Brazil.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:View_of_Corcovado_from_Sugarloaf_Mountain-Pao_de_Acucar_at_Sunset_-_Rio_de_Janeiro_-_Brazil.jpg' FROM TRILHA WHERE nome = 'Morro do Corcovado';
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Pedra da Gávea', 'Barra da Tijuca / São Conrado', 'Parque Nacional da Tijuca · Pedra da Gávea', 'SUL', -22.998982, -43.2829733, 0, '08:00', '17:00', 'Entrada das 8h às 14h; saída até 17h.', 'DIFICIL', 5.5, 270, 844, 'IDA_E_VOLTA', 'ESCALAMINHADA', 'ABERTA', 'Um dos maiores monólitos à beira-mar do mundo, com trecho de escalaminhada na Carrasqueira.', 'Trilha clássica do Parque Nacional da Tijuca. A subida atravessa mata fechada até o trecho da Carrasqueira, uma parede de rocha que exige técnica e, para a maioria, equipamento e guia. Do cume, a vista abrange a Barra, São Conrado, a Pedra Bonita e boa parte do litoral.', 'Portaria do parque na Estrada Sorimã, na Barra da Tijuca. Vá de carro ou aplicativo até o início da trilha.', TRUE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Huge_Pedra_da_Gavea_View_From_the_Beach.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Huge_Pedra_da_Gavea_View_From_the_Beach.jpg' FROM TRILHA WHERE nome = 'Pedra da Gávea';
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 1, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pedra_da_G%C3%A1vea_%282022-12-11%29_01.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Pedra_da_G%C3%A1vea_%282022-12-11%29_01.jpg' FROM TRILHA WHERE nome = 'Pedra da Gávea';
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sun_Setting_in_the_Ocean_Behind_Pedra_da_Gavea.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Sun_Setting_in_the_Ocean_Behind_Pedra_da_Gavea.jpg' FROM TRILHA WHERE nome = 'Pedra da Gávea';
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Pedra Bonita', 'São Conrado', 'Parque Nacional da Tijuca · Pedra da Gávea', 'SUL', -22.989182, -43.2840913, 0, '08:00', '16:00', 'Entrada das 8h às 16h.', 'FACIL', 3, 60, 693, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Subida curta até a rampa de voo livre, com vista para a Pedra da Gávea e o mar.', 'Ótima porta de entrada para quem está começando. A trilha é bem marcada e sombreada, terminando em um lajedo com vista panorâmica de São Conrado, da Barra e da Pedra da Gávea logo ao lado.', 'Estrada das Canoas até a rampa de voo livre; a trilha começa junto ao estacionamento.', TRUE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pedra_Bonita_10.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Pedra_Bonita_10.jpg' FROM TRILHA WHERE nome = 'Pedra Bonita';
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 1, 'https://commons.wikimedia.org/wiki/Special:FilePath/Monumento_Natural_Municipal_da_Pedra_Bonita_-_Bianca_Cunha_Duarte_%2801%29.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Monumento_Natural_Municipal_da_Pedra_Bonita_-_Bianca_Cunha_Duarte_%2801%29.jpg' FROM TRILHA WHERE nome = 'Pedra Bonita';
