INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Garganta do Céu', 'São Conrado', 'Parque Nacional da Tijuca · Pedra da Gávea', 'SUL', -22.9945, -43.283, 0, '08:00', '17:00', 'Entrada das 8h às 15h; saída até 17h.', 'MEDIO', 4.5, 180, NULL, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Trilha na Pedra da Gávea até o trecho conhecido como Garganta do Céu, com vista de São Conrado e do Dois Irmãos.', 'Percurso de cerca de 4,5 km ida e volta que sobe a Pedra da Gávea sem chegar ao cume. Exige preparo físico, mas evita o trecho técnico da Carrasqueira.', 'Portaria do parque na Estrada Sorimã, na Barra da Tijuca.', FALSE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Garganta_do_c%C3%A9u.JPG?width=1280', 'https://commons.wikimedia.org/wiki/File:Garganta_do_c%C3%A9u.JPG' FROM TRILHA WHERE nome = 'Garganta do Céu';
