INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Cachoeira Sorimã', 'Barra da Tijuca', 'Parque Nacional da Tijuca · Pedra da Gávea', 'SUL', -23.0035, -43.2885, 0, '08:00', NULL, 'Abre às 8h.', 'FACIL', 1, 15, NULL, 'IDA_E_VOLTA', 'CACHOEIRA', 'ABERTA', 'Cachoeira curta perto da Estrada Sorimã, no caminho para a Pedra da Gávea.', 'Cerca de 15 minutos de caminhada a partir da portaria do parque. Boa para se refrescar depois da subida à Pedra da Gávea.', 'Portaria do parque na Estrada Sorimã, na Barra da Tijuca.', FALSE);
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Agulhinha da Gávea', 'São Conrado', 'Parque Nacional da Tijuca · Pedra da Gávea', 'SUL', -22.9859721, -43.276992, 0, '08:00', '17:00', 'Das 8h às 17h.', 'FACIL', 1, 30, 610, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Pequena agulha de pedra com 610 m, vizinha à Pedra da Gávea, com vista de São Conrado.', 'Trilha curta, de cerca de 1 km ida e volta. Uma alternativa rápida para quem quer ver a Pedra da Gávea de perto sem encarar a subida completa.', 'Início da trilha em São Conrado.', FALSE);
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Pico da Pedra Branca', 'Taquara / Jacarepaguá', 'Parque Estadual da Pedra Branca', 'OESTE', -22.9317804, -43.4728977, 0, '08:00', '17:00', 'Das 8h às 17h.', 'DIFICIL', 17, 480, 1024, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Ponto mais alto da cidade do Rio, com 1.024 m, no Parque Estadual da Pedra Branca.', 'Subida longa e exigente a partir do núcleo Pau da Fome. Relatos indicam cerca de 8,5 km por trecho, então reserve o dia inteiro. A estrada de acesso pode fechar depois de chuvas fortes.', 'Núcleo Pau da Fome, na Estrada do Pau da Fome, 4003, Taquara.', FALSE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pico.da.Pedra.Branca.1025m.visto.do.bairro.de.Campo.Grande.Zona.Oeste.do.Rio.de.Janeiro.RJ.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Pico.da.Pedra.Branca.1025m.visto.do.bairro.de.Campo.Grande.Zona.Oeste.do.Rio.de.Janeiro.RJ.jpg' FROM TRILHA WHERE nome = 'Pico da Pedra Branca';
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Pedra do Quilombo', 'Jacarepaguá', 'Parque Estadual da Pedra Branca', 'OESTE', -22.9458665, -43.4355424, 0, '08:00', NULL, 'Abre às 8h.', 'MEDIO', 7, 210, 735, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Cume de 735 m no Parque Estadual da Pedra Branca.', 'Trilha de cerca de 7 km ida e volta pela Mata Atlântica do maciço da Pedra Branca, com vista para a Baixada de Jacarepaguá no topo.', 'Portaria do Parque Estadual da Pedra Branca.', FALSE);
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Cachoeira de Vargem Grande', 'Vargem Grande', 'Parque Estadual da Pedra Branca', 'OESTE', -22.9769474, -43.4999571, 0, '08:00', NULL, 'Abre às 8h.', 'FACIL', 3, 90, NULL, 'IDA_E_VOLTA', 'CACHOEIRA', 'ABERTA', 'Poços e quedas d''água no bairro de Vargem Grande, também conhecidos como Poço Dantas.', 'Caminhada de cerca de 3 km ida e volta pela mata até os poços. Boa para um banho de cachoeira na Zona Oeste.', 'Portaria do parque, em Vargem Grande.', FALSE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cachoeiras_de_Vargem_Grande_I.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Cachoeiras_de_Vargem_Grande_I.jpg' FROM TRILHA WHERE nome = 'Cachoeira de Vargem Grande';
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Cachoeiras da Pedra Branca', 'Jacarepaguá', 'Parque Estadual da Pedra Branca', 'OESTE', -22.9261251, -43.4285481, 0, '08:00', '17:00', 'Das 8h às 17h.', 'FACIL', 0, NULL, NULL, 'CIRCUITO', 'CACHOEIRA', 'ABERTA', 'Circuito pelas cachoeiras do Parque Estadual da Pedra Branca.', 'Roteiro em circuito pelos rios do maciço da Pedra Branca. Distância e duração ainda não foram levantadas. O acesso pode fechar depois de chuvas fortes.', 'Portaria do Parque Estadual da Pedra Branca.', FALSE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cachoeira_V%C3%A9u_da_Noiva_-_Pedra_Branca.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Cachoeira_V%C3%A9u_da_Noiva_-_Pedra_Branca.jpg' FROM TRILHA WHERE nome = 'Cachoeiras da Pedra Branca';
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Praias Selvagens de Guaratiba', 'Barra de Guaratiba', 'Reserva Ecológica de Guaratiba', 'OESTE', -23.0715699, -43.5524819, 0, NULL, NULL, 'Acesso 24 horas.', 'MEDIO', 5, 120, NULL, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Sequência de praias desertas: Perigoso, Meio, Funda, Inferno e Búzios.', 'Caminho costeiro que liga praias acessíveis apenas a pé ou de barco. Leve bastante água: há pouca sombra e nenhum comércio no percurso.', 'Início da trilha em Barra de Guaratiba, perto da Pedra do Telégrafo.', FALSE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Praia_do_Perigoso_-_Rio.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Praia_do_Perigoso_-_Rio.jpg' FROM TRILHA WHERE nome = 'Praias Selvagens de Guaratiba';
