INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Pedra da Tartaruga', 'Barra de Guaratiba', 'Reserva Ecológica de Guaratiba', 'OESTE', -23.0731826, -43.550652, 0, NULL, NULL, 'Acesso 24 horas.', 'MEDIO', 5, 120, 90, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Pedra em forma de casco de tartaruga, entre as praias selvagens de Guaratiba.', 'Trilha de cerca de 5 km ida e volta pelo litoral de Barra de Guaratiba. Do alto da pedra se veem as praias selvagens dos dois lados.', 'Início da trilha em Barra de Guaratiba.', FALSE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pedra_da_Tartaruga_Guaratiba.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Pedra_da_Tartaruga_Guaratiba.jpg' FROM TRILHA WHERE nome = 'Pedra da Tartaruga';
