INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Pedra do Telégrafo', 'Barra de Guaratiba', 'Reserva Ecológica de Guaratiba', 'OESTE', -23.0683165, -43.5582054, 0, NULL, NULL, 'Acesso 24 horas.', 'MEDIO', 2.5, 90, 345, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Famosa pela foto "pendurado" na pedra, com vista para as praias selvagens.', 'Subida curta e bem marcada. Além da famosa foto, o mirante revela a Restinga da Marambaia e as praias selvagens de Guaratiba. Fins de semana costumam ter fila para fotos.', 'Rua Belchior da Fonseca, em Barra de Guaratiba. Há estacionamentos particulares perto do início.', FALSE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vista_da_Pedra_do_Tel%C3%A9grafo_-_Barra_de_Guaratiba_-_Rio_de_Janeiro.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Vista_da_Pedra_do_Tel%C3%A9grafo_-_Barra_de_Guaratiba_-_Rio_de_Janeiro.jpg' FROM TRILHA WHERE nome = 'Pedra do Telégrafo';
