INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Travessia Grumari x Guaratiba', 'Grumari / Barra de Guaratiba', 'Reserva Ecológica de Guaratiba', 'OESTE', -23.0501519, -43.5341887, 0, NULL, NULL, 'Acesso 24 horas.', 'DIFICIL', 0, NULL, NULL, 'TRAVESSIA', 'CAMINHADA', 'ABERTA', 'Travessia pelo litoral entre Grumari e Barra de Guaratiba, passando pelas praias selvagens.', 'Percurso de ponta a ponta, difícil, com subidas e descidas entre as praias. Combine o transporte de volta antes de sair e leve bastante água.', 'Início na praia de Grumari (ou no sentido contrário, em Barra de Guaratiba).', FALSE);
