INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Mirante do Caeté', 'Grumari / Prainha', 'Parque Natural Municipal da Prainha', 'OESTE', -23.0331646, -43.5061536, 0, '08:00', '17:00', 'Das 8h às 17h.', 'FACIL', 2.5, 30, 130, 'CIRCUITO', 'CAMINHADA', 'ABERTA', 'Circuito curto no Parque da Prainha até um mirante sobre a Prainha e o Recreio.', 'Trilha bem cuidada, de cerca de 2,5 km em circuito, feita em uns 30 minutos. A vista da Prainha do alto é das mais bonitas da Zona Oeste.', 'Portaria do Parque Natural Municipal da Prainha.', FALSE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mirante_do_Caet%C3%A9_Prainha_Rio_de_Janeiro.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Mirante_do_Caet%C3%A9_Prainha_Rio_de_Janeiro.jpg' FROM TRILHA WHERE nome = 'Mirante do Caeté';
