INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Pedra do Pontal', 'Recreio dos Bandeirantes', NULL, 'OESTE', -23.0360866, -43.4699217, 0, NULL, NULL, 'Acesso 24 horas.', 'FACIL', 1, 30, 25, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Pedra no fim da praia do Recreio, com vista para toda a orla.', 'Subida curta, de cerca de 15 minutos por trecho. Com a maré baixa, uma faixa de areia liga a praia à pedra.', 'Início da trilha no Pontal, no fim da praia do Recreio.', FALSE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pedra_do_Pontal_-_Recreio_dos_Bandeirantes_-_Nascer_do_Sol.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Pedra_do_Pontal_-_Recreio_dos_Bandeirantes_-_Nascer_do_Sol.jpg' FROM TRILHA WHERE nome = 'Pedra do Pontal';
