INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Enseada do Bananal', 'Itacoatiara, Niterói', 'Parque Estadual da Serra da Tiririca', 'FORA_DO_RIO', -22.9741454, -43.025189, 0, '08:00', '17:00', 'Das 8h às 17h.', 'FACIL', 1, 20, NULL, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Trilha curta até uma pequena enseada no Parque Estadual da Serra da Tiririca.', 'Cerca de 20 minutos de caminhada a partir da portaria do parque, em Itacoatiara. A enseada também aparece do alto do Costão.', 'Portaria do parque, em Itacoatiara (Niterói).', FALSE);
INSERT INTO TRILHA_IMAGEM (idTrilha, ordem, url, creditoUrl) SELECT idTrilha, 0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Enseada_do_Bananal_ao_fundo.jpg?width=1280', 'https://commons.wikimedia.org/wiki/File:Enseada_do_Bananal_ao_fundo.jpg' FROM TRILHA WHERE nome = 'Enseada do Bananal';
INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Costão de Itacoatiara', 'Itacoatiara, Niterói', 'Parque Estadual da Serra da Tiririca', 'FORA_DO_RIO', -22.9777125, -43.0281699, 0, '08:00', NULL, 'Abre às 8h.', 'FACIL', 2, 60, 210, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Paredão de pedra sobre a praia de Itacoatiara, com vista do Rio e das praias de Niterói.', 'Subida de cerca de 1 hora ida e volta, com alguns trechos íngremes de rocha. Do alto se vê a praia de Itacoatiara e, em dias limpos, o Rio de Janeiro.', 'Portaria do parque, em Itacoatiara (Niterói).', FALSE);
