INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Pedra do Elefante (Alto Mourão)', 'Itacoatiara, Niterói', 'Parque Estadual da Serra da Tiririca', 'FORA_DO_RIO', -22.975828, -43.0207934, 0, '08:00', '17:00', 'Das 8h às 17h.', 'MEDIO', 4, 120, 412, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Ponto mais alto da Serra da Tiririca, com 412 m, entre Niterói e Maricá.', 'Trilha de cerca de 4 km ida e volta. Do topo se veem as praias da Região Oceânica de Niterói e as lagoas de Maricá.', 'Início da trilha em Itacoatiara (Niterói).', FALSE);
