INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Morro das Andorinhas', 'Itaipu, Niterói', 'Parque Estadual da Serra da Tiririca', 'FORA_DO_RIO', -22.979, -43.048, 0, '08:00', NULL, 'Abre às 8h.', 'FACIL', 0, 120, 196, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Mirante sobre as praias de Itaipu e Camboinhas e a Lagoa de Itaipu.', 'Trilha com uma sequência de mirantes costeiros e bastante sol. Passeios guiados levam cerca de 2 horas, com paradas.', 'Início na Rua da Amizade, em Itaipu (Niterói).', FALSE);
