INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Serra da Misericórdia', 'Penha / Complexo da Misericórdia', NULL, 'NORTE', -22.8547914, -43.2793835, 0, NULL, NULL, 'Fins de semana, com agendamento com guia local.', 'MEDIO', 4, 150, 300, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Maior área verde da Zona Norte, com mirantes e projetos de agroecologia.', 'Roteiros conduzidos por coletivos locais revelam mirantes sobre a Baía de Guanabara e iniciativas de agroecologia comunitária. Recomenda-se ir com guia da região.', 'Combine o ponto de encontro com um guia local (geralmente na Penha ou na Vila Cruzeiro).', FALSE);
