INSERT INTO TRILHA (nome, localizacao, parque, zona, latitude, longitude, taxa, horarioAbertura, horarioFechamento, observacaoHorario, dificuldade, distancia, duracaoMinutos, altitude, tipoPercurso, tipoAtividade, situacao, descricaoCurta, descricao, comoChegar, destaque) VALUES ('Pedra do Sino', 'Teresópolis', 'Parque Nacional da Serra dos Órgãos', 'FORA_DO_RIO', -22.4616667, -43.0311111, 45, '08:00', NULL, 'Portaria abre às 8h. Valor de ingresso sujeito a alteração.', 'DIFICIL', 22, 420, 2263, 'IDA_E_VOLTA', 'CAMINHADA', 'ABERTA', 'Ponto culminante da Serra dos Órgãos, com vista para o Dedo de Deus.', 'Subida longa e contínua no Parque Nacional da Serra dos Órgãos. Pode ser feita em bate-volta ou com pernoite no abrigo. Clima frio e mudanças rápidas de tempo: leve agasalho e capa de chuva.', 'Sede Teresópolis do PARNASO, na Av. Rotariana. Cerca de 1h30 de carro do Rio.', TRUE);
